import {supabaseServer} from '@/lib/supabase/server';export async function getUser(){const db=await supabaseServer();const {data:{user}}=await db.auth.getUser();return {db,user}}export async function isAdmin(){const {db,user}=await getUser();if(!user)return false;const {data}=await db.from('user_roles').select('role').eq('user_id',user.id).eq('role','admin').maybeSingle();return !!data}